import React from 'react';
import { ScrollView } from 'react-native-gesture-handler';

import Animated, {
  runOnJS,
  useAnimatedReaction,
  useAnimatedStyle,
  useDerivedValue,
  useSharedValue,
  withSpring,
  withTiming,
} from 'react-native-reanimated';

import {
  calculateMenuHeight,
  menuAnimationAnchor,
} from '../../utils/calculations';

import MenuItems from './MenuItems';

import {
  ABSOLUTE_FILL,
  SPRING_CONFIGURATION_MENU,
  HOLD_ITEM_TRANSFORM_DURATION,
  CONTEXT_MENU_STATE,
} from '../../constants';

import styles from './styles';
import { MenuItemProps } from './types';
import { useInternal } from '../../hooks';
import { deepEqual } from '../../utils/validations';
import { leftOrRight } from './calculations';

// gesture-handler's ScrollView is wrapped in a NativeViewGestureHandler, so on
// Android the RNGH orchestrator hands the drag to it instead of the backdrop's
// full-screen TapGestureHandler. With the plain react-native ScrollView the
// menu never starts scrolling on Android.
const AnimatedScrollView = Animated.createAnimatedComponent(ScrollView);

const MenuListComponent = () => {
  const { state, theme, menuProps } = useInternal();

  const [itemList, setItemList] = React.useState<MenuItemProps[]>([]);
  const [isScrollable, setIsScrollable] = React.useState(false);

  const menuHeight = useDerivedValue(() => {
    const itemsWithSeparator = menuProps.value.items.filter(
      item => item.withSeparator
    );
    return calculateMenuHeight(
      menuProps.value.items.length,
      itemsWithSeparator.length,
      menuProps.value.maxVisibleItems
    );
  }, [menuProps]);
  const prevList = useSharedValue<MenuItemProps[]>([]);

  const messageStyles = useAnimatedStyle(() => {
    const itemsWithSeparator = menuProps.value.items.filter(
      item => item.withSeparator
    );

    const translate = menuAnimationAnchor(
      menuProps.value.anchorPosition,
      menuProps.value.itemWidth,
      menuProps.value.items.length,
      itemsWithSeparator.length,
      menuProps.value.maxVisibleItems
    );

    const _leftPosition = leftOrRight(menuProps);

    const menuScaleAnimation = () =>
      state.value === CONTEXT_MENU_STATE.ACTIVE
        ? withSpring(1, SPRING_CONFIGURATION_MENU)
        : withTiming(0, {
            duration: HOLD_ITEM_TRANSFORM_DURATION,
          });

    const opacityAnimation = () =>
      withTiming(state.value === CONTEXT_MENU_STATE.ACTIVE ? 1 : 0, {
        duration: HOLD_ITEM_TRANSFORM_DURATION,
      });

    return {
      left: _leftPosition,
      height: menuHeight.value,
      opacity: opacityAnimation(),
      transform: [
        { translateX: translate.beginningTransformations.translateX },
        { translateY: translate.beginningTransformations.translateY },
        {
          scale: menuScaleAnimation(),
        },
        { translateX: translate.endingTransformations.translateX },
        { translateY: translate.endingTransformations.translateY },
      ],
    };
  });

  const animatedInnerContainerStyle = useAnimatedStyle(() => {
    const color = theme.value === 'light' ? '#fff' : '#1A1A1A';
    return {
      backgroundColor: color,
    };
  }, [theme]);

  const setter = (items: MenuItemProps[]) => {
    setItemList(items);
    prevList.value = items;
  };

  useAnimatedReaction(
    () => menuProps.value.items,
    _items => {
      if (!deepEqual(_items, prevList.value)) {
        runOnJS(setter)(_items);
      }
    },
    [menuProps]
  );

  useAnimatedReaction(
    () =>
      menuProps.value.maxVisibleItems > 0 &&
      menuProps.value.items.length > menuProps.value.maxVisibleItems,
    (scrollable, prevScrollable) => {
      if (scrollable !== prevScrollable) {
        runOnJS(setIsScrollable)(scrollable);
      }
    },
    [menuProps]
  );

  return (
    <Animated.View style={[styles.menuContainer, messageStyles]}>
      {isScrollable ? (
        <AnimatedScrollView
          style={[ABSOLUTE_FILL, animatedInnerContainerStyle]}
          contentContainerStyle={styles.menuInnerContainer}
          // The menu is only as tall as `maxVisibleItems` allows, so anything
          // past that is reached by scrolling.
          alwaysBounceVertical={false}
          nestedScrollEnabled
          // The menu floats in a portal, so iOS must not fold navigation bar
          // insets into its content offset.
          contentInsetAdjustmentBehavior={'never'}
        >
          <MenuItems items={itemList} />
        </AnimatedScrollView>
      ) : (
        // A list that fits is a plain view: on iOS 26 a scroll view draws the
        // system scroll edge effect over its top and blurs the first items.
        <Animated.View
          style={[
            ABSOLUTE_FILL,
            styles.menuInnerContainer,
            animatedInnerContainerStyle,
          ]}
        >
          <MenuItems items={itemList} />
        </Animated.View>
      )}
    </Animated.View>
  );
};

const MenuList = React.memo(MenuListComponent);

export default MenuList;
